import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import { Request, Response } from 'express';
import pdfParse from 'pdf-parse';

interface MulterRequest extends Request {
  file?: Express.Multer.File;
}

export const analyzeResume = async (req: MulterRequest, res: Response): Promise<void> => {
  try {
    if (!req.file) {
      res.status(400).json({ error: 'No PDF file uploaded.' });
      return;
    }

    const { jobDescription } = req.body;
    if (!jobDescription) {
      res.status(400).json({ error: 'Job description is required.' });
      return;
    }

    const pdfData = await pdfParse(req.file.buffer);
    const resumeText = pdfData.text.toLowerCase();

    // Extract potential keywords from job description (simple whitespace/punctuation tokenization)
    const rawKeywords = jobDescription
      .toLowerCase()
      .replace(/[^a-z0-9\s]/g, '')
      .split(/\s+/)
      .filter((word: string) => word.length > 3);

    const uniqueKeywords = Array.from(new Set<string>(rawKeywords)) as string[];
    const matched: string[] = [];
    const missing: string[] = [];

    uniqueKeywords.forEach((kw) => {
      if (resumeText.includes(kw)) {
        matched.push(kw);
      } else {
        missing.push(kw);
      }
    });

    const total = uniqueKeywords.length;
    const score = total > 0 ? Math.round((matched.length / total) * 100) : 0;

    res.status(200).json({
      score,
      matchedCount: matched.length,
      missingCount: missing.length,
      matched,
      missing,
    });
  } catch (error) {
    res.status(500).json({ error: 'Failed to parse PDF and calculate match score.' });
  }
};

import React, { useState } from 'react';

interface AnalysisResult {
  score: number;
  matched: string[];
  missing: string[];
}

export const ResumeScannerDashboard: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [jobDesc, setJobDesc] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<AnalysisResult | null>(null);

  const handleAnalyze = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!file || !jobDesc) return;

    setLoading(true);
    const formData = new FormData();
    formData.append('resume', file);
    formData.append('jobDescription', jobDesc);

    try {
      const res = await fetch('/api/analyze', {
        method: 'POST',
        body: formData,
      });
      const data = await res.json();
      setResult(data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto p-6 bg-slate-900 text-white rounded-xl shadow-2xl">
      <h1 className="text-3xl font-extrabold mb-6 text-indigo-400">AI Resume Keyword Scanner</h1>
      <form onSubmit={handleAnalyze} className="space-y-6">
        <div>
          <label className="block text-sm font-medium mb-2">Job Description</label>
          <textarea
            rows={5}
            className="w-full p-3 bg-slate-800 rounded-lg border border-slate-700 focus:ring-2 focus:ring-indigo-500"
            value={jobDesc}
            onChange={(e) => setJobDesc(e.target.value)}
            placeholder="Paste job requirements here..."
          />
        </div>
        <div>
          <label className="block text-sm font-medium mb-2">Upload Resume (PDF)</label>
          <input
            type="file"
            accept=".pdf"
            onChange={(e) => e.target.files && setFile(e.target.files[0])}
            className="w-full text-slate-400 file:mr-4 file:py-2 file:px-4 file:rounded-lg file:border-0 file:bg-indigo-600 file:text-white hover:file:bg-indigo-700"
          />
        </div>
        <button
          type="submit"
          disabled={loading}
          className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 rounded-lg font-semibold transition-all disabled:opacity-50"
        >
          {loading ? 'Analyzing...' : 'Scan Resume'}
        </button>
      </form>

      {result && (
        <div className="mt-8 p-6 bg-slate-800 rounded-xl border border-slate-700">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-xl font-bold">Match Score</h2>
            <span className="text-3xl font-black text-emerald-400">{result.score}%</span>
          </div>
          <div className="w-full bg-slate-700 h-4 rounded-full overflow-hidden mb-6">
            <div className="bg-emerald-500 h-full transition-all duration-500" style={{ width: `${result.score}%` }} />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <h3 className="font-semibold text-emerald-400 mb-2">Matched Keywords</h3>
              <div className="flex flex-wrap gap-2">
                {result.matched.map((kw, i) => (
                  <span key={i} className="px-2.5 py-1 bg-emerald-900/50 text-emerald-300 rounded text-xs">{kw}</span>
                ))}
              </div>
            </div>
            <div>
              <h3 className="font-semibold text-rose-400 mb-2">Missing Keywords</h3>
              <div className="flex flex-wrap gap-2">
                {result.missing.map((kw, i) => (
                  <span key={i} className="px-2.5 py-1 bg-rose-900/50 text-rose-300 rounded text-xs">{kw}</span>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};
